let base_path = "outputs/trace-diag-coding-modelprobe";
let existing_folders = JSON.parse('{{outputs_dir_contents}}');
let max_num = -1; // -1 means no base or numbered variants found

for (let item of existing_folders) {
  if (item === "trace-diag-coding-modelprobe") {
    max_num = Math.max(max_num, 0); // Treat base name as number 0 for incrementing
  } else {
    let match = item.match(/^trace-diag-coding-modelprobe-(\d+)$/);
    if (match) {
      max_num = Math.max(max_num, parseInt(match[1]));
    }
  }
}

if (max_num === -1) { // No base or numbered variants found
  return base_path;
} else {
  return base_path + "-" + (max_num + 1);
}

