{
  "name": "trace-diag-coding-modelprobe",
  "version": "1.0.0",
  "description": "Node.js Express server with /ok endpoint",
  "main": "server.js",
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "test": "node test.js"
  },
  "dependencies": {
    "express": "^4.17.1"
  },
  "devDependencies": {
    "supertest": "^6.1.3"
  }
}

import express from 'express';

const app = express();
const port = 3000;

app.get('/ok', (req, res) => {
  res.json({ ok: true });
});

app.listen(port, () => {
  console.log(`Server listening at http://localhost:${port}`);
});

export default app; // Export for testing

import request from 'supertest';
import app from './server.js'; // Import the Express app

async function runTests() {
  try {
    const response = await request(app).get('/ok');
    console.log('Test /ok endpoint:');
    console.log('Status:', response.statusCode);
    console.log('Body:', response.body);

    if (response.statusCode === 200 && response.body.ok === true) {
      console.log('Test passed: /ok endpoint returns {"ok":true}');
    } else {
      console.error('Test failed: /ok endpoint did not return expected result.');
      process.exit(1);
    }
  } catch (error) {
    console.error('Test failed with error:', error);
    process.exit(1);
  }
}

runTests();

